export const FeaturedVideo: React.FC<FeaturedVideoProps> = ({
  title = "Featured Video",
  initialVideos,
}) => {
  const [videoList, setVideoList] = useState<VideoItem[]>(
    initialVideos !== undefined ? initialVideos : []
  );
  const [activeVideo, setActiveVideo] = useState<VideoItem | null>(null);

  useEffect(() => {
    if (initialVideos !== undefined) {
      setVideoList(initialVideos);
      return;
    }

    let isMounted = true;
    const fetchFeaturedVideos = async () => {
      try {
        const res = await apiFetch(`${API_BASE_URL}/media?featured=true&limit=4`);
        if (res.ok) {
          const json = await res.json();
          const fetchedData: VideoItem[] = json.data || (Array.isArray(json) ? json : []);
          if (isMounted) {
            setVideoList(fetchedData);
          }
        }
      } catch (err) {
        console.error("Failed to fetch featured videos from backend", err);
      }
    };

    fetchFeaturedVideos();
    return () => {
      isMounted = false;
    };
  }, [initialVideos]);

  if (!videoList || videoList.length === 0) {
    return null;
  }

  const renderVideoCard = (video: VideoItem) => {
    const thumbnailUrl =
      video.thumbnail ||
      getYouTubeThumbnail(video.youtubeUrl || video.youtubeId || "");

    return (
      <div
        key={video.id}
        onClick={() => setActiveVideo(video)}
        className="group flex flex-col cursor-pointer"
      >
        {/* Thumbnail Frame with Play Overlay */}
        <div className="relative w-full aspect-video rounded-2xl sm:rounded-[22px] overflow-hidden bg-slate-900 shadow-xs group-hover:shadow-md transition-all duration-300">
          {thumbnailUrl ? (
            <Image
              src={thumbnailUrl}
              alt={video.title}
              fill
              sizes="(max-width: 768px) 100vw, 50vw"
              className="object-cover group-hover:scale-105 transition-transform duration-500"
              unoptimized
            />
          ) : (
            <div className="w-full h-full bg-slate-800 flex items-center justify-center text-slate-400 text-xs">
              No Thumbnail
            </div>
          )}

          {/* Play Button Overlay */}
          <div className="absolute inset-0 flex items-center justify-center bg-black/15 group-hover:bg-black/25 transition-colors">
            <div className="w-12 h-12 sm:w-14 sm:h-14 rounded-full bg-white/80 backdrop-blur-xs flex items-center justify-center text-gray-900 group-hover:scale-110 group-hover:bg-white transition-all duration-300 shadow-md border border-white/60">
              <Play className="w-4 h-4 sm:w-5 sm:h-5 fill-gray-900 text-gray-900 ml-0.5" />
            </div>
          </div>
        </div>

        {/* Video Caption Text Below Thumbnail */}
        <h3 className="text-sm sm:text-lg  text-dark-bg leading-snug line-clamp-2 mt-3.5 sm:mt-4 group-hover:text-black transition-colors">
          {video.title}
        </h3>
      </div>
    );
  };

  return (
    <section className="relative z-10 w-full bg-white py-14 sm:py-20 lg:py-24 font-poppins overflow-x-clip">
      {/* Decorative Floating Malayalam Vector Letters */}
      {/* Top Left Outline */}
      <div className="absolute -top-10 sm:-top-14 md:-top-16 lg:-top-20 -left-6 sm:-left-4 lg:left-0 pointer-events-none select-none z-20">
        <DummySvgFour className="w-20 sm:w-24 md:w-28 lg:w-36 h-auto" />
      </div>

      {/* Top Right: 'ക' Outline */}
      <div className="absolute top-1 sm:top-3 lg:top-10 -right-10 pointer-events-none select-none ">
        <DummySvgTwo className="w-24 sm:w-28 md:w-32 lg:w-40 h-auto" />
      </div>

      {/* Bottom Left: 'അ' Outline */}
      <div className="absolute bottom-4 sm:bottom-6 lg:bottom-1/2 left-0 pointer-events-none select-none ">
        <DummySvgOne className="w-28 sm:w-36 md:w-44 lg:w-52 h-auto" />
      </div>

      {/* Bottom Right: 'ം' Circle Outline */}
      <div className="absolute bottom-2 sm:bottom-4 lg:bottom-6 -right-4 sm:-right-3 lg:right-6 pointer-events-none select-none ">
        <DummySvgThree className="w-16 sm:w-18 md:w-22 lg:w-28 h-auto" />
      </div>

      <div className="container px-4  mx-auto relative z-10 max-w-6xl">
        {/* Centered Section Header */}
        <div className="text-center mb-10 lg:mb-14">
          <h2 className="text-3xl sm:text-4xl lg:text-5xl font-medium text-dark-text tracking-tight">
            {title}
          </h2>
        </div>

        {/* 2x2 Video Cards Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-10 sm:gap-x-20 sm:gap-y-12 w-full">
          {videoList.slice(0, 4).map((video) => renderVideoCard(video))}
        </div>

        {/* Explore All Button - Mobile Only (Appears after all 4 video cards) */}
        <div className="flex justify-center mt-8">
          <Link href="/media">
            <Button
              variant="primary"
              size="md"
              icon={<ArrowRight className="w-4 h-4 ml-1 transition-transform group-hover:translate-x-1" />}
              iconPosition="right"
              className="group px-6 py-2.5 text-sm font-medium shadow-xs cursor-pointer"
            >
              <span>Explore All</span>
            </Button>
          </Link>
        </div>
      </div>

      {/* Minimalist Lightbox Video Player Modal */}
      {activeVideo && (
        <div
          className="fixed inset-0 z-50 bg-black/85 backdrop-blur-md flex items-center justify-center p-4 sm:p-6 animate-in fade-in duration-200"
          onClick={() => setActiveVideo(null)}
        >
          <div
            className="relative w-full max-w-4xl bg-black rounded-2xl sm:rounded-3xl overflow-hidden shadow-2xl border border-white/10"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Close Button */}
            <button
              onClick={() => setActiveVideo(null)}
              className="absolute top-3 sm:top-4 right-3 sm:right-4 z-20 p-2 bg-black/60 hover:bg-black text-white rounded-full transition-colors cursor-pointer border border-white/20"
              aria-label="Close Video"
            >
              <X className="w-5 h-5" />
            </button>

            {/* 16:9 YouTube Widescreen Player */}
            <div className="relative w-full aspect-video bg-black">
              <iframe
                src={`${getYouTubeEmbedUrl(activeVideo.youtubeUrl || activeVideo.youtubeId || "")}?autoplay=1`}
                title={activeVideo.title}
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
                className="w-full h-full border-0"
              />
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

export default FeaturedVideo;
